async function expectText(read: () => Promise<string> | string, expected: string, timeoutMs = 1000, intervalMs = 20): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  let last = '';
  for (;;) {
    last = (await read()).trim();
    if (last === expected) return;
    if (Date.now() >= deadline) {
      throw new Error(`Expected "${expected}" but got "${last}"`);
    }
    await new Promise<void>((r) => setTimeout(r, intervalMs));
  }
}

coding.prompt:
Model `page.route` for tests. Write a class `Router` with:

- `route(pattern: string, body: unknown, status = 200)` registering a handler. In the pattern, `**` matches any characters (including `/`) and `*` matches any characters except `/`.
- `fetch(url: string): { status: number; body: unknown }` returning the response of the **most recently registered** matching route, or `{ status: 404, body: null }` if none match.

```ts
const r = new Router();
r.route('**/api/items', [1, 2]);
r.fetch('https://shop.test/api/items') // { status: 200, body: [1, 2] }
```

