  route(pattern: string, body: unknown, status = 200): void {}
  fetch(url: string): { status: number; body: unknown } {
    return { status: 0, body: undefined };
  }
}

coding.solution:
class Router {
  private routes: { re: RegExp; status: number; body: unknown }[] = [];

  private static toRegExp(glob: string): RegExp {
    let out = '';
    for (let i = 0; i < glob.length; i++) {
      const c = glob[i];
      if (c === '*' && glob[i + 1] === '*') { out += '.*'; i++; }
      else if (c === '*') out += '[^/]*';
      else out += c.replace(/[.+?^${}()|[\]\\]/g, '\\$&');
    }
    return new RegExp('^' + out + '$');
  }

  route(pattern: string, body: unknown, status = 200): void {
    this.routes.push({ re: Router.toRegExp(pattern), status, body });
  }

  fetch(url: string): { status: number; body: unknown } {
    for (let i = this.routes.length - 1; i >= 0; i--) {
      const r = this.routes[i];
      if (r.re.test(url)) return { status: r.status, body: r.body };
    }
    return { status: 404, body: null };
  }
}
